import { Loader2, Sparkles, Tag, X } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { t } from '../../src/shared/i18n';
import { MAX_PAPER_TAGS, MAX_TAG_CHARS, changeTags, normalizeTags, type PaperSummary, type TagCount } from '../../src/shared/types';
import { api, fail, jobsStore, toast, useFetch, useStore } from './lib';

const SEPARATORS = /[,，、]/;

/** The tags of the open paper, which can be edited by hand or generated by an agent. */
export function PaperTags({ paper, onChange }: { paper: PaperSummary; onChange(paper: PaperSummary): void }) {
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState('');
  const root = useRef<HTMLDivElement>(null);
  const { data: known } = useFetch<TagCount[]>(open ? '/tags' : null);
  const jobs = useStore(jobsStore);
  const generating = Object.values(jobs).some((j) => j.kind === 'tags' && j.paperId === paper.id && j.status === 'running');
  const canGenerate = paper.textChars >= 50 || Boolean(paper.abstract);

  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (!root.current?.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setOpen(false);
    document.addEventListener('mousedown', onDown);
    window.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDown);
      window.removeEventListener('keydown', onKey);
    };
  }, [open]);

  const save = async (tags: string[]) => {
    try {
      onChange(await api<PaperSummary>(`/papers/${paper.id}`, { method: 'PATCH', body: { tags } }));
    } catch (err) {
      fail(err);
    }
  };

  const commit = (text: string) => {
    const added = normalizeTags(text.split(SEPARATORS));
    setDraft('');
    if (!added.length) return;
    const next = changeTags(paper.tags, added);
    if (next.length > MAX_PAPER_TAGS) toast(t('一篇论文最多 {count} 个标签', { count: MAX_PAPER_TAGS }), 'error');
    else if (next.length > paper.tags.length) void save(next);
  };

  const offered = known?.filter(({ tag }) => !paper.tags.some((own) => own.toLowerCase() === tag.toLowerCase())) ?? [];

  return (
    <div className="tag-menu" ref={root}>
      <button className={`icon tag-toggle ${open ? 'on' : ''}`} title={t('标签')} aria-label={t('标签')} aria-expanded={open} onClick={() => setOpen(!open)}>
        {generating ? <Loader2 size={15} className="spin" /> : <Tag size={15} />}
        {paper.tags.length > 0 && <span className="mono">{paper.tags.length}</span>}
      </button>
      {open && (
        <div className="tag-pop" role="dialog" aria-label={t('标签')}>
          {paper.tags.length ? (
            <div className="tag-list">
              {paper.tags.map((tag) => (
                <span className="tag" key={tag}>
                  <span>{tag}</span>
                  <button title={t('移除标签：{tag}', { tag })} aria-label={t('移除标签：{tag}', { tag })} onClick={() => void save(changeTags(paper.tags, [], [tag]))}>
                    <X size={11} />
                  </button>
                </span>
              ))}
            </div>
          ) : (
            <p className="muted small">{t('还没有标签')}</p>
          )}
          <input
            autoFocus
            list="tag-options"
            maxLength={MAX_TAG_CHARS * 2}
            aria-label={t('输入标签后按回车')}
            placeholder={t('输入标签后按回车')}
            value={draft}
            onChange={(e) => {
              const { value } = e.target;
              if (SEPARATORS.test(value) && !(e.nativeEvent as InputEvent).isComposing) commit(value);
              else setDraft(value);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.nativeEvent.isComposing) {
                e.preventDefault();
                commit(draft);
              }
              if (e.key === 'Backspace' && !draft && paper.tags.length) void save(paper.tags.slice(0, -1));
            }}
            onBlur={() => commit(draft)}
          />
          <datalist id="tag-options">
            {offered.map(({ tag }) => <option key={tag} value={tag} />)}
          </datalist>
          <button
            className="btn small tag-generate"
            disabled={generating || !canGenerate}
            title={canGenerate ? t('论文的标题、摘要和开头部分会发送给你选择的 Agent 服务。') : t('这份 PDF 没有可提取的文字（可能是扫描件），暂时无法生成内容。')}
            onClick={() => api(`/papers/${paper.id}/tags/generate`, { method: 'POST' }).catch(fail)}
          >
            {generating ? <Loader2 size={13} className="spin" /> : <Sparkles size={13} />}
            {generating ? t('正在生成标签') : t('用 Agent 生成')}
          </button>
        </div>
      )}
    </div>
  );
}
